"""Unit tests for the admin question-management service."""

import tempfile
import unittest
from pathlib import Path

from spacefractions.admin.service import AdminService
from spacefractions.question.models import QuestionType
from spacefractions.storage.database import Database
from spacefractions.storage.question_repository import QuestionRepository


class AdminServiceTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.db = Database(Path(self.tmp.name) / "test.db")
        self.db.init_schema()
        self.service = AdminService(QuestionRepository(self.db))

    def tearDown(self):
        self.tmp.cleanup()

    def test_add_and_delete(self):
        question = self.service.add_question("What is 1/2 + 1/2?", ["1", "1/2", "1/4", "2"], "1", QuestionType.ADD)
        self.assertEqual(len(self.service.list_questions()), 1)
        self.assertTrue(self.service.delete_question(question.id))
        self.assertEqual(self.service.list_questions(), [])

    def test_rejects_answer_not_in_options(self):
        with self.assertRaises(ValueError):
            self.service.add_question("prompt", ["a", "b"], "c", QuestionType.COMPARE)


if __name__ == "__main__":
    unittest.main()
